# Durable on-device mastery.
mastery = ROOT / 'app/src/main/java/com/example/learning/MasteryRepository.kt'
mastery.parent.mkdir(parents=True, exist_ok=True)
mastery.write_text('''package com.example.learning\n\nimport android.content.Context\nimport org.json.JSONObject\nimport java.util.Locale\n\ndata class TopicMastery(val topic: String, val attempts: Int, val correct: Int, val streak: Int, val masteryPercent: Int, val lastUpdated: Long)\n\n/** Durable instructional telemetry kept on-device; no cloud sync. */\nobject MasteryRepository {\n    private const val PREFS = "learner_mastery_v2"\n    private const val PREFIX = "profile_"\n\n    fun record(context: Context, profileId: Long, subject: String, topic: String, correct: Boolean, now: Long = System.currentTimeMillis()) {\n        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)\n        val root = runCatching { JSONObject(prefs.getString(PREFIX + profileId, "{}") ?: "{}") }.getOrDefault(JSONObject())\n        val subjectKey = subject.trim().uppercase(Locale.US).ifBlank { "GENERAL" }\n        val topicKey = topic.trim().ifBlank { "GENERAL" }\n        val subjects = root.optJSONObject(subjectKey) ?: JSONObject().also { root.put(subjectKey, it) }\n        val current = subjects.optJSONObject(topicKey) ?: JSONObject()\n        val attempts = current.optInt("attempts") + 1\n        val correctCount = current.optInt("correct") + if (correct) 1 else 0\n        val streak = if (correct) current.optInt("streak") + 1 else 0\n        val accuracyScore = ((correctCount.toDouble() / attempts.toDouble()) * 70.0).toInt()\n        val streakScore = (streak * 5).coerceAtMost(30)\n        current.put("attempts", attempts).put("correct", correctCount).put("streak", streak)\n            .put("masteryPercent", (accuracyScore + streakScore).coerceIn(0, 100)).put("lastUpdated", now)\n        subjects.put(topicKey, current)\n        prefs.edit().putString(PREFIX + profileId, root.toString()).apply()\n    }\n\n    fun snapshot(context: Context, profileId: Long): List<TopicMastery> {\n        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)\n        val root = runCatching { JSONObject(prefs.getString(PREFIX + profileId, "{}") ?: "{}") }.getOrDefault(JSONObject())\n        val result = mutableListOf<TopicMastery>()\n        root.keys().forEach { subject ->\n            val topics = root.optJSONObject(subject) ?: return@forEach\n            topics.keys().forEach { topic ->\n                val item = topics.optJSONObject(topic) ?: return@forEach\n                result += TopicMastery(topic, item.optInt("attempts"), item.optInt("correct"), item.optInt("streak"), item.optInt("masteryPercent"), item.optLong("lastUpdated"))\n            }\n        }\n        return result.sortedByDescending { it.lastUpdated }\n    }\n\n    fun overallMastery(context: Context, profileId: Long): Int = snapshot(context, profileId).let { if (it.isEmpty()) 0 else it.map { item -> item.masteryPercent }.average().toInt() }\n}\n''')

# Hardware capability layer.
hw = ROOT / 'app/src/main/java/com/example/network/LocalAiHardwareManager.kt'
hw.parent.mkdir(parents=True, exist_ok=True)
hw.write_text('''package com.example.network\n\nimport android.app.ActivityManager\nimport android.content.Context\nimport android.os.Build\nimport java.io.File\n\nenum class LocalAiBackend { NPU, GPU, CPU, CLOUD, UNAVAILABLE }\ndata class LocalAiHardwareCapabilities(val socManufacturer: String, val socModel: String, val totalRamGb: Float, val arm64: Boolean, val potentialNpuModel: String?, val gpuModelAvailable: Boolean, val summary: String)\n\nobject LocalAiHardwareManager {\n    private const val MODEL_DIR = "models/litert"\n\n    fun inspect(context: Context): LocalAiHardwareCapabilities {\n        val info = ActivityManager.MemoryInfo()\n        (context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager)?.getMemoryInfo(info)\n        val ram = info.totalMem / (1024f * 1024f * 1024f)\n        val npu = npuModelName(Build.SOC_MANUFACTURER, Build.SOC_MODEL)\n        val gpu = genericGpuModelFile(context).exists()\n        val summary = when {\n            npu != null -> "NPU-ready model target detected for ${Build.SOC_MANUFACTURER} ${Build.SOC_MODEL}; accelerator is only reported active after LiteRT-LM initialization succeeds."\n            gpu -> "GPU-ready LiteRT model installed; accelerator is only reported active after LiteRT-LM initialization succeeds."\n            else -> "No accelerator-ready LiteRT model installed; GGUF/llama.cpp CPU/NEON remains available."\n        }\n        return LocalAiHardwareCapabilities(Build.SOC_MANUFACTURER, Build.SOC_MODEL, ram, Build.SUPPORTED_ABIS.contains("arm64-v8a"), npu, gpu, summary)\n    }\n\n    fun modelDirectory(context: Context): File = File(context.filesDir, MODEL_DIR).also { it.mkdirs() }\n    fun genericGpuModelFile(context: Context): File = File(modelDirectory(context), "gemma3-1b-it-int4.litertlm")\n\n    fun npuModelName(manufacturer: String, model: String): String? {\n        val m = model.lowercase()\n        return when {\n            manufacturer.equals("Qualcomm", true) && m.contains("sm8550") -> "Gemma3-1B-IT_q4_ekv1280_sm8550.litertlm"\n            manufacturer.equals("Qualcomm", true) && m.contains("sm8650") -> "Gemma3-1B-IT_q4_ekv1280_sm8650.litertlm"\n            manufacturer.equals("Qualcomm", true) && m.contains("sm8750") -> "Gemma3-1B-IT_q4_ekv1280_sm8750.litertlm"\n            manufacturer.equals("Qualcomm", true) && m.contains("sm8850") -> "Gemma3-1B-IT_q4_ekv1280_sm8850.litertlm"\n            manufacturer.equals("MediaTek", true) && m.contains("mt6989") -> "Gemma3-1B-IT_q4_ekv1280_mt6989.litertlm"\n            manufacturer.equals("MediaTek", true) && m.contains("mt6991") -> "Gemma3-1B-IT_q4_ekv1280_mt6991.litertlm"\n            manufacturer.equals("MediaTek", true) && m.contains("mt6993") -> "Gemma3-1B-IT_q4_ekv1280_mt6993.litertlm"\n            manufacturer.equals("Google", true) && m.contains("g5") -> "Gemma3-1B-IT_q8_ekv1280_Google_Tensor_G5.litertlm"\n            manufacturer.equals("Google", true) && m.contains("g6") -> "Gemma3-1B-IT_q8_ekv1280_Google_Tensor_G6.litertlm"\n            else -> null\n        }\n    }\n\n    fun orderedCandidates(modelFile: File): List<LocalAiBackend> = if (modelFile.name.lowercase().contains(Regex("sm8550|sm8650|sm8750|sm8850|mt6989|mt6991|mt6993|tensor"))) listOf(LocalAiBackend.NPU, LocalAiBackend.GPU, LocalAiBackend.CPU) else listOf(LocalAiBackend.GPU, LocalAiBackend.CPU)\n}\n''')

# Real LiteRT-LM model download and runtime fallback chain.
lm = ROOT / 'app/src/main/java/com/example/network/LiteRtGemmaManager.kt'
lm.write_text('''package com.example.network\n\nimport android.content.Context\nimport android.util.Log\nimport com.google.ai.edge.litertlm.Backend\nimport com.google.ai.edge.litertlm.ConversationConfig\nimport com.google.ai.edge.litertlm.Engine\nimport com.google.ai.edge.litertlm.EngineConfig\nimport com.google.ai.edge.litertlm.ThinkingConfig\nimport kotlinx.coroutines.Dispatchers\nimport kotlinx.coroutines.withContext\nimport okhttp3.OkHttpClient\nimport okhttp3.Request\nimport java.io.File\nimport java.io.FileOutputStream\nimport java.util.concurrent.TimeUnit\n\ndata class LocalAiInferenceMetrics(val backend: LocalAiBackend, val model: String, val modelLoadMs: Long, val totalGenerationMs: Long, val responseChars: Int)\n\nobject LiteRtGemmaManager {\n    private const val TAG = "LiteRtGemmaManager"\n    private const val HF_BASE = "https://huggingface.co/litert-community/Gemma3-1B-IT/resolve/main/"\n    private val client = OkHttpClient.Builder().connectTimeout(30, TimeUnit.SECONDS).readTimeout(10, TimeUnit.MINUTES).build()\n    @Volatile var lastMetrics: LocalAiInferenceMetrics? = null\n        private set\n\n    fun modelFile(context: Context): File {\n        val caps = LocalAiHardwareManager.inspect(context)\n        return File(LocalAiHardwareManager.modelDirectory(context), caps.potentialNpuModel ?: "gemma3-1b-it-int4.litertlm")\n    }\n\n    suspend fun downloadAcceleratedModel(context: Context, hfToken: String): Result<File> = withContext(Dispatchers.IO) {\n        val token = hfToken.trim()\n        if (token.isBlank()) return@withContext Result.failure(IllegalArgumentException("A Hugging Face access token is required for the gated LiteRT Gemma model. Accept the Gemma license first."))\n        val filename = LocalAiHardwareManager.inspect(context).potentialNpuModel ?: "gemma3-1b-it-int4.litertlm"\n        val target = File(LocalAiHardwareManager.modelDirectory(context), filename)\n        if (target.exists() && target.length() > 100_000_000L && isLiteRtModel(target)) return@withContext Result.success(target)\n        runCatching {\n            val temp = File(target.parentFile, target.name + ".tmp")\n            temp.delete()\n            val request = Request.Builder().url(HF_BASE + filename + "?download=true").header("Authorization", "Bearer $token").header("User-Agent", "NeuroPath-Android/2.00.00").build()\n            client.newCall(request).execute().use { response ->\n                check(response.isSuccessful) { "LiteRT Gemma download failed: HTTP ${response.code}" }\n                val body = response.body ?: error("Empty LiteRT Gemma response")\n                body.byteStream().use { input -> FileOutputStream(temp).use { output -> input.copyTo(output, 256 * 1024); output.fd.sync() } }\n            }\n            check(isLiteRtModel(temp)) { "Downloaded LiteRT Gemma file is not a valid LITERTLM container" }\n            target.delete()\n            check(temp.renameTo(target)) { "Could not install LiteRT Gemma model" }\n            target\n        }\n    }\n\n    suspend fun generateResponse(context: Context, prompt: String, systemPrompt: String, maxTokens: Int): String? = withContext(Dispatchers.Default) {\n        val model = modelFile(context)\n        if (!model.exists() || !isLiteRtModel(model)) return@withContext null\n        var lastError: Throwable? = null\n        for (backend in LocalAiHardwareManager.orderedCandidates(model)) {\n            val start = System.nanoTime()\n            try {\n                val engineConfig = EngineConfig(\n                    modelPath = model.absolutePath,\n                    backend = when (backend) {\n                        LocalAiBackend.NPU -> Backend.NPU(context.applicationInfo.nativeLibraryDir)\n                        LocalAiBackend.GPU -> Backend.GPU()\n                        else -> Backend.CPU()\n                    },\n                    cacheDir = context.cacheDir.absolutePath\n                )\n                Engine(engineConfig).use { engine ->\n                    engine.initialize()\n                    val loadMs = (System.nanoTime() - start) / 1_000_000L\n                    engine.createConversation(ConversationConfig(systemInstruction = com.google.ai.edge.litertlm.Contents.of(systemPrompt), maxOutputToken = maxTokens, thinkingConfig = ThinkingConfig(enableThinking = false))).use { conversation ->\n                        val generationStart = System.nanoTime()\n                        val reply = conversation.sendMessage(prompt).text.trim()\n                        val totalMs = (System.nanoTime() - generationStart) / 1_000_000L\n                        if (reply.isNotBlank()) {\n                            lastMetrics = LocalAiInferenceMetrics(backend, model.name, loadMs, totalMs, reply.length)\n                            return@withContext reply\n                        }\n                    }\n                }\n            } catch (t: Throwable) {\n                lastError = t\n                Log.w(TAG, "LiteRT ${backend.name} failed; trying next backend", t)\n            }\n        }\n        Log.w(TAG, "No LiteRT backend succeeded", lastError)\n        null\n    }\n\n    private fun isLiteRtModel(file: File): Boolean = runCatching { file.inputStream().use { input -> val magic = ByteArray(8); input.read(magic) == 8 && String(magic, Charsets.US_ASCII) == "LITERTLM" } }.getOrDefault(false)\n}\n''')

